#!/usr/bin/env python3
from pathlib import Path

root = Path(__file__).resolve().parents[2]

# Public AST surface: an aggregate integer slot may carry the same symbolic
# object+member+addend identity as a pointer slot, while retaining its integer
# destination type for target validation and emission.
h = root / "src/frontend/ast.h"
text = h.read_text()
anchor = '''bool minic_c0_global_object_add_object_relocation_path_addend_cast(\n    MinicC0Program *program,\n    MinicGlobalObjectId global_object_id,\n    MinicGlobalRelocationLocationKind location_kind,\n    size_t location_index,\n    MinicGlobalObjectId target_object_id,\n    const size_t *target_member_indices,\n    size_t target_member_depth,\n    int64_t target_byte_addend);\n'''
insert = anchor + '''bool minic_c0_global_object_add_integer_object_relocation_path_addend(\n    MinicC0Program *program,\n    MinicGlobalObjectId global_object_id,\n    MinicGlobalRelocationLocationKind location_kind,\n    size_t location_index,\n    MinicGlobalObjectId target_object_id,\n    const size_t *target_member_indices,\n    size_t target_member_depth,\n    int64_t target_byte_addend);\n'''
if text.count(anchor) != 1:
    raise SystemExit(f"ast.h relocation declaration anchor count={text.count(anchor)}")
h.write_text(text.replace(anchor, insert, 1))

# AST relocation ownership: keep pointer compatibility unchanged. Integer slots
# are admitted only as symbolic-address carriers; target-width legality remains a
# target verifier responsibility.
c = root / "src/frontend/ast_global.c"
text = c.read_text()
old_slot = '''    if (location_kind == MINIC_GLOBAL_RELOCATION_LOCATION_AGGREGATE_SCALAR) {\n        size_t remaining;\n\n        remaining = location_index;\n        return aggregate_scalar_slot_type(program, object->type, &remaining, slot_type) &&\n               minic_type_is_pointer(*slot_type);\n    }\n'''
new_slot = '''    if (location_kind == MINIC_GLOBAL_RELOCATION_LOCATION_AGGREGATE_SCALAR) {\n        size_t remaining;\n\n        remaining = location_index;\n        return aggregate_scalar_slot_type(program, object->type, &remaining, slot_type) &&\n               (minic_type_is_pointer(*slot_type) || minic_type_is_integer(*slot_type));\n    }\n'''
if text.count(old_slot) != 1:
    raise SystemExit(f"ast_global slot anchor count={text.count(old_slot)}")
text = text.replace(old_slot, new_slot, 1)

old_decls = '''    MinicType slot_pointee;\n    MinicType slot_type;\n    MinicType target_type;\n    size_t insertion_index;\n'''
new_decls = '''    MinicType slot_pointee;\n    MinicType slot_type;\n    MinicType target_type;\n    bool slot_is_integer;\n    bool slot_is_pointer;\n    size_t insertion_index;\n'''
if text.count(old_decls) != 1:
    raise SystemExit(f"ast_global relocation decl anchor count={text.count(old_decls)}")
text = text.replace(old_decls, new_decls, 1)

old_validate = '''    object = &program->global_objects[global_object_id];\n    if (!minic_c0_global_relocation_slot_type(\n            program, object, location_kind, location_index, &slot_type) ||\n        !minic_type_pointee(slot_type, &slot_pointee) ||\n        (target_kind == MINIC_GLOBAL_RELOCATION_FUNCTION &&\n         !minic_c0_global_relocation_function_target_compatible(\n             program, slot_type, (MinicFunctionId)target_id, has_explicit_pointer_cast)) ||\n        (target_kind == MINIC_GLOBAL_RELOCATION_OBJECT && minic_type_is_function(slot_pointee) &&\n         !has_explicit_pointer_cast) ||\n        (target_kind == MINIC_GLOBAL_RELOCATION_OBJECT &&\n         (!global_object_member_path_type(program,\n                                          &program->global_objects[target_id],\n                                          target_member_indices,\n                                          target_member_depth,\n                                          &target_type) ||\n          !global_relocation_object_target_type_compatible(\n              program, slot_type, target_type, has_explicit_pointer_cast))) ||\n        object->is_tentative ||\n'''
new_validate = '''    object = &program->global_objects[global_object_id];\n    if (!minic_c0_global_relocation_slot_type(\n            program, object, location_kind, location_index, &slot_type)) {\n        return false;\n    }\n    slot_is_pointer = minic_type_is_pointer(slot_type);\n    slot_is_integer = minic_type_is_integer(slot_type);\n    if ((!slot_is_pointer && !slot_is_integer) ||\n        (slot_is_pointer && !minic_type_pointee(slot_type, &slot_pointee)) ||\n        (target_kind == MINIC_GLOBAL_RELOCATION_FUNCTION && slot_is_pointer &&\n         !minic_c0_global_relocation_function_target_compatible(\n             program, slot_type, (MinicFunctionId)target_id, has_explicit_pointer_cast)) ||\n        (target_kind == MINIC_GLOBAL_RELOCATION_OBJECT && slot_is_pointer &&\n         minic_type_is_function(slot_pointee) && !has_explicit_pointer_cast) ||\n        (target_kind == MINIC_GLOBAL_RELOCATION_OBJECT &&\n         (!global_object_member_path_type(program,\n                                          &program->global_objects[target_id],\n                                          target_member_indices,\n                                          target_member_depth,\n                                          &target_type) ||\n          (slot_is_pointer &&\n           !global_relocation_object_target_type_compatible(\n               program, slot_type, target_type, has_explicit_pointer_cast)))) ||\n        object->is_tentative ||\n'''
if text.count(old_validate) != 1:
    raise SystemExit(f"ast_global validation anchor count={text.count(old_validate)}")
text = text.replace(old_validate, new_validate, 1)

anchor_impl = '''bool minic_c0_global_object_add_object_relocation_path(\n    MinicC0Program *program,\n'''
impl = '''bool minic_c0_global_object_add_integer_object_relocation_path_addend(\n    MinicC0Program *program,\n    MinicGlobalObjectId global_object_id,\n    MinicGlobalRelocationLocationKind location_kind,\n    size_t location_index,\n    MinicGlobalObjectId target_object_id,\n    const size_t *target_member_indices,\n    size_t target_member_depth,\n    int64_t target_byte_addend) {\n    MinicType slot_type;\n\n    if (program == NULL || global_object_id >= program->global_object_count ||\n        !minic_c0_global_relocation_slot_type(program,\n                                              &program->global_objects[global_object_id],\n                                              location_kind,\n                                              location_index,\n                                              &slot_type) ||\n        !minic_type_is_integer(slot_type)) {\n        return false;\n    }\n    return add_global_symbol_relocation(program,\n                                        global_object_id,\n                                        location_kind,\n                                        location_index,\n                                        MINIC_GLOBAL_RELOCATION_OBJECT,\n                                        target_object_id,\n                                        target_member_indices,\n                                        target_member_depth,\n                                        target_byte_addend,\n                                        false);\n}\n\n'''
if text.count(anchor_impl) != 1:
    raise SystemExit(f"ast_global implementation anchor count={text.count(anchor_impl)}")
text = text.replace(anchor_impl, impl + anchor_impl, 1)
c.write_text(text)

# Data-layout owner: resolve aggregate relocation width from the actual slot type
# instead of assuming every relocation occupies a pointer-typed slot. Mirror the
# zero-slot skip rule already used by AST aggregate traversal.
d = root / "src/target/data_layout.c"
text = d.read_text()
old_array_progress = '''            if (*slot_index == before) {\n                return false;\n            }\n'''
new_array_progress = '''            if (*slot_index == before) {\n                size_t child_slots;\n\n                if (!minic_c0_global_initializer_slot_count(\n                        program, array_type->element_type, &child_slots) ||\n                    child_slots != 0U) {\n                    return false;\n                }\n            }\n'''
# There are two progress guards (array + record); replace them contextually below.
array_context = '''            if (aggregate_scalar_slot_layout(layout,\n                                             program,\n                                             array_type->element_type,\n                                             base_offset + element_index * element_size,\n                                             slot_index,\n                                             slot_type,\n                                             slot_offset)) {\n                return true;\n            }\n            if (*slot_index == before) {\n                return false;\n            }\n'''
array_new = '''            if (aggregate_scalar_slot_layout(layout,\n                                             program,\n                                             array_type->element_type,\n                                             base_offset + element_index * element_size,\n                                             slot_index,\n                                             slot_type,\n                                             slot_offset)) {\n                return true;\n            }\n            if (*slot_index == before) {\n                size_t child_slots;\n\n                if (!minic_c0_global_initializer_slot_count(\n                        program, array_type->element_type, &child_slots) ||\n                    child_slots != 0U) {\n                    return false;\n                }\n            }\n'''
record_context = '''                if (aggregate_scalar_slot_layout(layout,\n                                                 program,\n                                                 field->type,\n                                                 base_offset + field_offset +\n                                                     element_index * element_size,\n                                                 slot_index,\n                                                 slot_type,\n                                                 slot_offset)) {\n                    return true;\n                }\n                if (*slot_index == before) {\n                    return false;\n                }\n'''
record_new = '''                if (aggregate_scalar_slot_layout(layout,\n                                                 program,\n                                                 field->type,\n                                                 base_offset + field_offset +\n                                                     element_index * element_size,\n                                                 slot_index,\n                                                 slot_type,\n                                                 slot_offset)) {\n                    return true;\n                }\n                if (*slot_index == before) {\n                    size_t child_slots;\n\n                    if (!minic_c0_global_initializer_slot_count(\n                            program, field->type, &child_slots) ||\n                        child_slots != 0U) {\n                        return false;\n                    }\n                }\n'''
for old, new, label in [
    (array_context, array_new, "data-layout array progress"),
    (record_context, record_new, "data-layout record progress"),
]:
    if text.count(old) != 1:
        raise SystemExit(f"{label} anchor count={text.count(old)}")
    text = text.replace(old, new, 1)

old_vars = '''    size_t object_alignment;\n    size_t object_size;\n    size_t resolved_offset;\n'''
new_vars = '''    size_t object_alignment;\n    size_t object_size;\n    size_t relocation_width;\n    size_t resolved_offset;\n'''
if text.count(old_vars) != 1:
    raise SystemExit(f"data-layout relocation vars anchor count={text.count(old_vars)}")
text = text.replace(old_vars, new_vars, 1)
old_init = '''    (void)object_alignment;\n    if (relocation->location_kind == MINIC_GLOBAL_RELOCATION_LOCATION_SCALAR) {\n'''
new_init = '''    (void)object_alignment;\n    relocation_width = layout->pointer_size;\n    if (relocation->location_kind == MINIC_GLOBAL_RELOCATION_LOCATION_SCALAR) {\n'''
if text.count(old_init) != 1:
    raise SystemExit(f"data-layout relocation width init anchor count={text.count(old_init)}")
text = text.replace(old_init, new_init, 1)
old_agg = '''    } else if (relocation->location_kind == MINIC_GLOBAL_RELOCATION_LOCATION_AGGREGATE_SCALAR) {\n        MinicType slot_type;\n        size_t remaining;\n\n        remaining = relocation->location_index;\n        if (!aggregate_scalar_slot_layout(\n                layout, program, object->type, 0U, &remaining, &slot_type, &resolved_offset) ||\n            !minic_type_is_pointer(slot_type)) {\n            return false;\n        }\n    } else {\n        return false;\n    }\n    if (resolved_offset > object_size || layout->pointer_size > object_size - resolved_offset) {\n'''
new_agg = '''    } else if (relocation->location_kind == MINIC_GLOBAL_RELOCATION_LOCATION_AGGREGATE_SCALAR) {\n        MinicType slot_type;\n        size_t remaining;\n        size_t slot_alignment;\n\n        remaining = relocation->location_index;\n        if (!aggregate_scalar_slot_layout(\n                layout, program, object->type, 0U, &remaining, &slot_type, &resolved_offset) ||\n            (!minic_type_is_pointer(slot_type) && !minic_type_is_integer(slot_type)) ||\n            !minic_data_layout_type(\n                layout, program, slot_type, &relocation_width, &slot_alignment)) {\n            return false;\n        }\n        (void)slot_alignment;\n    } else {\n        return false;\n    }\n    if (resolved_offset > object_size || relocation_width > object_size - resolved_offset) {\n'''
if text.count(old_agg) != 1:
    raise SystemExit(f"data-layout aggregate relocation anchor count={text.count(old_agg)}")
text = text.replace(old_agg, new_agg, 1)
d.write_text(text)

# Verifier: integer-address relocations are target-dependent. Keep them only when
# the integer slot exactly matches pointer storage width; pointer relocations keep
# all existing C type-compatibility checks.
v = root / "src/frontend/ast_verifier.c"
text = v.read_text()
old_loop = '''                const MinicGlobalRelocation *relocation;\n                MinicType slot_pointee;\n                MinicType slot_type;\n\n                relocation = &object->relocations[relocation_index];\n                if (!minic_c0_global_relocation_slot_type(program,\n                                                          object,\n                                                          relocation->location_kind,\n                                                          relocation->location_index,\n                                                          &slot_type)) {\n                    return false;\n                }\n                if (!minic_type_pointee(slot_type, &slot_pointee) ||\n                    (relocation_index != 0U &&\n                     (object->relocations[relocation_index - 1U].location_kind !=\n                          relocation->location_kind ||\n                      object->relocations[relocation_index - 1U].location_index >=\n                          relocation->location_index)) ||\n                    (relocation->target_kind == MINIC_GLOBAL_RELOCATION_OBJECT &&\n                     (relocation->target_id >= program->global_object_count ||\n                      (minic_type_is_function(slot_pointee) &&\n                       !relocation->has_explicit_pointer_cast))) ||\n                    (relocation->target_kind == MINIC_GLOBAL_RELOCATION_FUNCTION &&\n                     !minic_c0_global_relocation_function_target_compatible(\n                         program,\n                         slot_type,\n                         (MinicFunctionId)relocation->target_id,\n                         relocation->has_explicit_pointer_cast)) ||\n                    (relocation->target_kind != MINIC_GLOBAL_RELOCATION_OBJECT &&\n                     relocation->target_kind != MINIC_GLOBAL_RELOCATION_FUNCTION)) {\n                    return false;\n                }\n                if (relocation->target_kind == MINIC_GLOBAL_RELOCATION_OBJECT &&\n                    !minic_c0_global_relocation_object_target_compatible(\n                        program, relocation, slot_type)) {\n                    return false;\n                }\n'''
new_loop = '''                const MinicGlobalRelocation *relocation;\n                const MinicDataLayout *layout;\n                MinicType slot_pointee;\n                MinicType slot_type;\n                size_t slot_alignment;\n                size_t slot_size;\n                bool slot_is_integer;\n                bool slot_is_pointer;\n\n                relocation = &object->relocations[relocation_index];\n                layout = minic_target_info_data_layout(target);\n                if (layout == NULL ||\n                    !minic_c0_global_relocation_slot_type(program,\n                                                          object,\n                                                          relocation->location_kind,\n                                                          relocation->location_index,\n                                                          &slot_type)) {\n                    return false;\n                }\n                slot_is_pointer = minic_type_is_pointer(slot_type);\n                slot_is_integer = minic_type_is_integer(slot_type);\n                if ((!slot_is_pointer && !slot_is_integer) ||\n                    (slot_is_integer &&\n                     (!minic_data_layout_type(\n                          layout, program, slot_type, &slot_size, &slot_alignment) ||\n                      slot_size != layout->pointer_size)) ||\n                    (slot_is_pointer && !minic_type_pointee(slot_type, &slot_pointee)) ||\n                    (relocation_index != 0U &&\n                     (object->relocations[relocation_index - 1U].location_kind !=\n                          relocation->location_kind ||\n                      object->relocations[relocation_index - 1U].location_index >=\n                          relocation->location_index)) ||\n                    (relocation->target_kind == MINIC_GLOBAL_RELOCATION_OBJECT &&\n                     (relocation->target_id >= program->global_object_count ||\n                      (slot_is_pointer && minic_type_is_function(slot_pointee) &&\n                       !relocation->has_explicit_pointer_cast))) ||\n                    (relocation->target_kind == MINIC_GLOBAL_RELOCATION_FUNCTION &&\n                     ((slot_is_pointer &&\n                       !minic_c0_global_relocation_function_target_compatible(\n                           program,\n                           slot_type,\n                           (MinicFunctionId)relocation->target_id,\n                           relocation->has_explicit_pointer_cast)) ||\n                      (slot_is_integer && relocation->target_id >= program->function_count))) ||\n                    (relocation->target_kind != MINIC_GLOBAL_RELOCATION_OBJECT &&\n                     relocation->target_kind != MINIC_GLOBAL_RELOCATION_FUNCTION)) {\n                    return false;\n                }\n                if (slot_is_pointer &&\n                    relocation->target_kind == MINIC_GLOBAL_RELOCATION_OBJECT &&\n                    !minic_c0_global_relocation_object_target_compatible(\n                        program, relocation, slot_type)) {\n                    return false;\n                }\n'''
if text.count(old_loop) != 1:
    raise SystemExit(f"verifier relocation loop anchor count={text.count(old_loop)}")
text = text.replace(old_loop, new_loop, 1)
v.write_text(text)

# RV64 global writer: a symbolic aggregate scalar is emitted using the actual
# scalar width. The verifier has already guaranteed integer-address slots are
# pointer-width on this target.
r = root / "src/target/riscv64/codegen_function.c"
text = r.read_text()
old_direct = '''            if (!minic_type_is_pointer(field->type) || value != 0U ||\n                !minic_riscv64_emit_symbol_value(file, program, relocation, field_size)) {\n'''
new_direct = '''            if ((!minic_type_is_pointer(field->type) && !minic_type_is_integer(field->type)) ||\n                value != 0U ||\n                !minic_riscv64_emit_symbol_value(file, program, relocation, field_size)) {\n'''
if text.count(old_direct) != 1:
    raise SystemExit(f"rv64 direct record relocation anchor count={text.count(old_direct)}")
text = text.replace(old_direct, new_direct, 1)
old_recursive = '''            if (!minic_type_is_pointer(type) || bits != 0U ||\n                !minic_riscv64_emit_symbol_value(file, program, relocation, type_size)) {\n'''
new_recursive = '''            if ((!minic_type_is_pointer(type) && !minic_type_is_integer(type)) || bits != 0U ||\n                !minic_riscv64_emit_symbol_value(file, program, relocation, type_size)) {\n'''
if text.count(old_recursive) != 1:
    raise SystemExit(f"rv64 recursive relocation anchor count={text.count(old_recursive)}")
text = text.replace(old_recursive, new_recursive, 1)
r.write_text(text)

# Parser: recognize a symbolic integer address expression after normal C parsing.
# Integer +/- integer-constant addends use raw byte units (unlike pointer
# arithmetic, which is scaled before reaching the relocation model).
p = root / "src/frontend/parser_global.c"
text = p.read_text()
anchor_helper = '''static bool parse_static_scalar_constant_at(MinicParser *parser,\n                                            MinicGlobalObjectId object_id,\n                                            MinicType type,\n                                            bool overwrite,\n                                            size_t overwrite_slot) {\n'''
helper = '''static bool static_integer_address_constant_delta(const MinicParser *parser,\n                                                  MinicExpressionId expression_id,\n                                                  int64_t *delta) {\n    MinicConstValue value;\n\n    return parser != NULL && delta != NULL &&\n           minic_const_eval_integer(\n               parser->program, parser->target_info, expression_id, &value) &&\n           minic_const_value_as_int64(\n               parser->program, parser->target_info, &value, delta);\n}\n\nstatic bool static_integer_address_relocation_target(\n    const MinicParser *parser,\n    MinicExpressionId expression_id,\n    MinicStaticObjectRelocationTarget *target) {\n    const MinicExpression *expression;\n\n    if (parser == NULL || target == NULL) {\n        return false;\n    }\n    expression = minic_c0_program_expression(parser->program, expression_id);\n    if (expression == NULL || !minic_type_is_integer(expression->type)) {\n        return false;\n    }\n    if (expression->kind == MINIC_EXPRESSION_CAST ||\n        expression->kind == MINIC_EXPRESSION_BITCAST ||\n        expression->kind == MINIC_EXPRESSION_CONVERSION) {\n        const MinicExpression *operand;\n\n        operand = minic_c0_program_expression(parser->program, expression->value.unary.operand);\n        if (operand != NULL && minic_type_is_pointer(operand->type)) {\n            return static_object_address_relocation_path(\n                parser, expression->value.unary.operand, target);\n        }\n        return static_integer_address_relocation_target(\n            parser, expression->value.unary.operand, target);\n    }\n    if (expression->kind == MINIC_EXPRESSION_BINARY &&\n        (expression->value.binary.operator_kind == MINIC_BINARY_ADD ||\n         expression->value.binary.operator_kind == MINIC_BINARY_SUBTRACT)) {\n        MinicStaticObjectRelocationTarget base;\n        int64_t delta;\n\n        if (static_integer_address_relocation_target(\n                parser, expression->value.binary.left, &base) &&\n            static_integer_address_constant_delta(\n                parser, expression->value.binary.right, &delta)) {\n            if (expression->value.binary.operator_kind == MINIC_BINARY_SUBTRACT) {\n                if (delta == INT64_MIN) {\n                    return false;\n                }\n                delta = -delta;\n            }\n            if (!static_add_pointer_offset(base.byte_addend, delta, &base.byte_addend)) {\n                return false;\n            }\n            *target = base;\n            return true;\n        }\n        if (expression->value.binary.operator_kind == MINIC_BINARY_ADD &&\n            static_integer_address_constant_delta(\n                parser, expression->value.binary.left, &delta) &&\n            static_integer_address_relocation_target(\n                parser, expression->value.binary.right, &base) &&\n            static_add_pointer_offset(base.byte_addend, delta, &base.byte_addend)) {\n            *target = base;\n            return true;\n        }\n    }\n    return false;\n}\n\nstatic bool static_integer_address_slot_supported(const MinicParser *parser, MinicType type) {\n    const MinicDataLayout *layout;\n    size_t alignment;\n    size_t size;\n\n    layout = parser == NULL ? NULL : minic_target_info_data_layout(parser->target_info);\n    return layout != NULL && minic_type_is_integer(type) &&\n           minic_data_layout_type(layout, parser->program, type, &size, &alignment) &&\n           size == layout->pointer_size;\n}\n\n'''
if text.count(anchor_helper) != 1:
    raise SystemExit(f"parser helper insertion anchor count={text.count(anchor_helper)}")
text = text.replace(anchor_helper, helper + anchor_helper, 1)

old_integer = '''    if (minic_type_is_integer(type)) {\n        uint64_t parsed_bits;\n\n        if (!minic_parser_parse_integer_initializer_bits(parser, type, &parsed_bits)) {\n            return false;\n        }\n        if (overwrite) {\n            if (!minic_c0_global_object_replace_zero_initializer_bits(\n                    parser->program, object_id, overwrite_slot, parsed_bits)) {\n                minic_parser_error(\n                    parser,\n                    "backward static record designator can only replace an implicit scalar zero");\n                return false;\n            }\n        } else if (!minic_c0_global_object_add_initializer_bits(\n                       parser->program, object_id, parsed_bits)) {\n            minic_parser_error(parser, "cannot record static aggregate integer initializer");\n            return false;\n        }\n'''
new_integer = '''    if (minic_type_is_integer(type)) {\n        MinicConstValue constant;\n        MinicConstValue converted;\n        MinicExpressionId expression_id;\n        MinicStaticObjectRelocationTarget relocation_target;\n        uint64_t parsed_bits;\n        bool has_symbolic_address;\n\n        if (!minic_parser_parse_expression(parser, &expression_id, 0U)) {\n            return false;\n        }\n        if (minic_const_eval_integer(\n                parser->program, parser->target_info, expression_id, &constant) &&\n            minic_const_value_convert_integer(\n                parser->program, parser->target_info, &constant, type, &converted)) {\n            parsed_bits = converted.bits;\n            has_symbolic_address = false;\n        } else if (static_integer_address_slot_supported(parser, type) &&\n                   static_integer_address_relocation_target(\n                       parser, expression_id, &relocation_target)) {\n            parsed_bits = 0U;\n            has_symbolic_address = true;\n        } else {\n            minic_parser_error(\n                parser, "integer initializer requires an integer constant expression");\n            return false;\n        }\n        if (overwrite) {\n            if (!minic_c0_global_object_replace_zero_initializer_bits(\n                    parser->program, object_id, overwrite_slot, parsed_bits)) {\n                minic_parser_error(\n                    parser,\n                    "backward static record designator can only replace an implicit scalar zero");\n                return false;\n            }\n        } else if (!minic_c0_global_object_add_initializer_bits(\n                       parser->program, object_id, parsed_bits)) {\n            minic_parser_error(parser, "cannot record static aggregate integer initializer");\n            return false;\n        }\n        if (has_symbolic_address &&\n            !minic_c0_global_object_add_integer_object_relocation_path_addend(\n                parser->program,\n                object_id,\n                MINIC_GLOBAL_RELOCATION_LOCATION_AGGREGATE_SCALAR,\n                overwrite ? overwrite_slot\n                          : parser->program->global_objects[object_id].initializer_count - 1U,\n                relocation_target.object_id,\n                relocation_target.member_indices,\n                relocation_target.member_depth,\n                relocation_target.byte_addend)) {\n            minic_parser_error(parser, "cannot record static symbolic integer relocation");\n            return false;\n        }\n'''
if text.count(old_integer) != 1:
    raise SystemExit(f"parser aggregate integer anchor count={text.count(old_integer)}")
text = text.replace(old_integer, new_integer, 1)
p.write_text(text)
